// war3map.j as the World Editor writes it on save: globals, object creation
// (sounds, regions, cameras, units, …), the triggers converted to JASS, player
// setup, main and config. Each section is generated by its own function so it
// can be compared on its own with the World Editor's output (the game's maps
// carry both the trigger data and the script the editor made from it).
// Work in progress: not every section is generated yet.

import { parseSlk } from "../formats/text";
import { jassToLua, RAW } from "./lua";
import { ident } from "./names";
import { nameDepthOfField } from "../terrain/cameras";
import type { TriggerData } from "../triggers/triggerdata";
import type { CustomTextFile, TriggerFile, Variable } from "../triggers/wtg";
import { customTextGlobals, runsAtInit, scriptItems, triggersSection } from "./triggers";
import { configSection, mainSection, playersSection, type SetupInput } from "./setup";
import { fixed, itemsSection, unitsSection, type UnitJson } from "./units";
import { dropSection, itemTablesSection, randomGroupsSection, type DropItem, type Dropper, type RandomGroupJson } from "./drops";
import { destructablesSection, type DestructableJson } from "./destructables";
import { techTreeSection, upgradesSection, type TechJson, type UpgradeJson } from "./techs";

// ---- inputs (the format engine's JSON) ----------------------------------------------

export interface MapInfoJson {
  name: string;
  author: string;
  description: string;
  [k: string]: unknown;
}
export interface RegionJson { left: number; bottom: number; right: number; top: number; name: string; index: number; weather: string; sound: string }
export interface CameraJson {
  targetX: number; targetY: number; zOffset: number; rotation: number; angleOfAttack: number; distance: number; roll: number;
  fieldOfView: number; farZ: number; nearZ: number; localPitch?: number; localYaw?: number; localRoll?: number;
  /** Version 3 only (lib/terrain/cameras: DEPTH_OF_FIELD); JSON from before they had names has them in `unknown`. */
  dofDistance?: number; dofScale?: number; posAbsoluteZ?: number; unknown?: number[];
  name: string; trailer?: number;
}
export interface SoundJson {
  name: string; file: string; eaxEffect: string; flags: number; fadeInRate: number; fadeOutRate: number; volume: number;
  pitch: number; pitchVariance: number; priority: number; channel: number; minDistance: number; maxDistance: number;
  distanceCutoff: number; coneInside: number; coneOutside: number; coneOutsideVolume: number; coneOrientation: number[];
  variableName?: string; assetLabel?: string; assetFile?: string; dialogueTextKey?: number; speakerNameKey?: number;
  facialAnimationLabel?: string; facialAnimationGroupLabel?: string; facialAnimationSetFile?: string;
  speakerUnitType?: string; unknown2?: number;
}

/** A placed object (war3mapUnits.doo / war3map.doo JSON entry). */
export interface PlacedJson { id: string; editorId: number; [k: string]: unknown }

export interface ScriptInput {
  info: MapInfoJson;
  /** Units and items (war3mapUnits.doo), doodads and destructables (war3map.doo). */
  units?: PlacedJson[];
  doodads?: PlacedJson[];
  data: TriggerData;
  triggers?: TriggerFile;
  custom?: CustomTextFile | null;
  regions?: RegionJson[];
  cameras?: CameraJson[];
  sounds?: SoundJson[];
  /** "TRIGSTR_n" → text, for the header. */
  string?: (value: string) => string;
  /** What an object id is (custom ids by their base and the map's changes). */
  kindOf?: (id: string) => "building" | "unit" | "item" | "sloc" | "ability" | undefined;
  /** Team colour a unit type has in the map's object data (lib/script/objects). */
  teamColor?: (id: string) => number | undefined;
  /** Whether a custom unit type is a gold mine or a waygate (lib/script/objects). */
  goldMine?: (id: string) => boolean;
  waygate?: (id: string) => boolean;
  /** Whether a unit type allows a custom team colour (lib/script/objects customColorTypes). */
  customColor?: (id: string) => boolean;
  /** The orders that turn an ability's autocast on and off. */
  autocastOrders?: (ability: string) => { on: string; off?: string } | undefined;
  /** Whether an ability is a hero ability (lib/script/objects heroAbilities). */
  heroAbility?: (ability: string) => boolean;
  /** The tint of a destructable type in the map's object data (lib/script/objects destructableTints). */
  destructableTint?: (id: string) => [number, number, number];
  /** Day/night models for the map's light environment (WorldEditData [TerrainLights]/[UnitLights]). */
  lights?: { terrain: string; unit: string };
  /** Ground height at a point (for region ambient sounds). */
  groundHeight?: (x: number, y: number) => number;
  /** Length of a sound file in milliseconds (SetSoundDuration), if known; `name` is the sound's (gg_snd_…): sounds
   *  whose file can't be read keep their own (three of "---Invalid Sound Filepath---" in Roundabout, each its own). */
  soundDuration?: (file: string, name: string) => number | undefined;
  /** A sound label's settings (UI\SoundInfo\*.slk), for labelled sounds. */
  soundLabel?: (label: string) => SoundLabel | undefined;
  /** Generate for war3map.lua (set by generateScript for Lua maps). */
  lua?: boolean;
}

// ---- helpers ---------------------------------------------------------------------------

const EOL = "\r\n";
const STARS = "//***************************************************************************";
/** Section banner as the World Editor writes it. */
export function banner(title: string): string {
  return ["//***************************************************************************", "//*", `//*  ${title}`, "//*",
    "//***************************************************************************", ""].join(EOL) + EOL;
}
export { ident };
/** Reals with one decimal, as in Rect( 3936.0, … ). */
const r1 = (v: number) => fixed(v, 1); // map values are 32-bit floats
/** A JASS string literal. */
export const str = (s: string) => `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
/** Unset sound values are 2^32 (4294967300 after a round trip through JSON). */
const unset = (v: number) => v >= 4e9;

/** A typed value as JASS source: strings quoted, object codes as 'hfoo'. */
export function literal(data: TriggerData, type: string, value: string): string {
  const base = jassType(data, type);
  if (base === "string") return str(value);
  if (base === "integer" && /code$/.test(type) && value.length === 4) return `'${value}'`;
  return value;
}

/** The JASS type behind a trigger type (custom types like unitcode are integers). */
export function jassType(data: TriggerData, type: string): string {
  return data.types.get(type)?.base ?? type;
}

// ---- sections ----------------------------------------------------------------------------

export function header(i: ScriptInput): string {
  const s = i.string ?? ((v: string) => v);
  return ["//===========================================================================", "// ", `// ${s(i.info.name)}`, "// ",
    "//   Warcraft III map script", "//   Generated by the Warcraft III World Editor",
    `//   Map Author: ${s(i.info.author)}`, "// ",
    "//===========================================================================", "", ""].join(EOL);
}

/** Default value of a global in its declaration (only non-handle types have one). JASS declares a string
 *  without a value and a real as `0`; war3map.lua has `""` and `0.0` (World Editor, 2026-11-12). */
function declDefault(i: ScriptInput, type: string): string {
  const base = jassType(i.data, type);
  if (base === "boolean") return "false";
  if (base === "integer") return "0";
  if (base === "real") return i.lua ? "0.0" : "0";
  if (base === "string") return i.lua ? '""' : "";
  return "null";
}

function globalLine(type: string, name: string, value?: string): string {
  const t = `    ${type.padEnd(24)}`;
  return !value ? `${t}${name}` : `${t}${name.padEnd(26)} = ${value}`;
}

export function globals(i: ScriptInput): string {
  const vars = i.triggers?.variables ?? [];
  const lines = ["globals", ...(vars.length ? ["    // User-defined"] : [])];
  for (const v of vars) {
    const t = jassType(i.data, v.type);
    lines.push(v.isArray ? globalLine(`${t} array`, `udg_${v.name}`) : globalLine(t, `udg_${v.name}`, declDefault(i, v.type)));
  }
  if (vars.length) lines.push("");
  lines.push("    // Generated");
  // Objects with the same name share one global.
  const declared = new Set<string>();
  const gen = (type: string, name: string, value?: string) => {
    if (!declared.has(name)) { declared.add(name); lines.push(globalLine(type, name, value)); }
  };
  for (const r of sortedRegions(i)) gen("rect", `gg_rct_${ident(r.name)}`, "null");
  for (const c of i.cameras ?? []) gen("camerasetup", `gg_cam_${ident(c.name)}`, "null");
  // Music is a file path, not a sound object.
  for (const s of i.sounds ?? []) { if (s.flags & 8) gen("string", s.name); else gen("sound", s.name, "null"); }
  for (const t of triggerItems(i)) gen("trigger", `gg_trg_${ident(t.name)}`, "null");
  const used = referencedGlobals(i);
  for (const u of i.units ?? []) {
    const n = placedName(u, "unit");
    if (used.has(n)) gen("unit", n, "null");
    else if (used.has(placedName(u, "item"))) gen("item", placedName(u, "item"), "null");
  }
  for (const d of i.doodads ?? []) if (used.has(placedName(d, "dest"))) gen("destructable", placedName(d, "dest"), "null");
  const tables = (i.info.unitTables as { number: number }[] | undefined) ?? [];
  if (tables.length) lines.push("", "    // Random Groups", ...tables.map((t) => `    integer array gg_rg_${String(t.number).padStart(3, "0")}`));
  lines.push("endglobals", "");
  return lines.join(EOL) + EOL;
}

/** gg_unit_hfoo_0012: object id and the placement's creation number (doodad
 *  files v13 keep it as the first trailer value, older ones and units in editorId). */
export const placedName = (p: PlacedJson, kind: string) => {
  const trailer = p.trailer as number[] | undefined;
  const n = trailer?.length === 3 ? trailer[0] : p.editorId;
  return `gg_${kind}_${p.id}_${String(n).padStart(4, "0")}`;
};

/** Generated globals the triggers refer to (gg_unit_…, gg_item_…, gg_dest_…), GUI and custom text. Disabled code
 *  declares them too, but with `compiled` only what runs counts: that decides what gets assigned. */
function referencedGlobals(i: ScriptInput, compiled = false): Set<string> {
  const out = i.triggers ? customTextGlobals({ triggers: i.triggers, custom: i.custom }, compiled) : new Set<string>();
  type P = { type: number; value: string; call?: { params: P[] }; index?: P };
  type E = { enabled: boolean; params: P[]; children: E[] };
  const visitP = (p: P) => { if (p.type === 1 && p.value.startsWith("gg_")) out.add(p.value); p.call?.params.forEach(visitP); if (p.index) visitP(p.index); };
  const visit = (e: E) => { if (compiled && !e.enabled) return; e.params.forEach(visitP); e.children.forEach(visit); };
  for (const t of triggerItems(i)) if (!compiled || (t.enabled && !t.isComment)) t.ecas.forEach(visit);
  return out;
}

/** Regions in the World Editor's order: by name, comparing character codes. */
function sortedRegions(i: ScriptInput): RegionJson[] {
  return i.regions ?? [];
}

/** Triggers (not variables, and not script items: type 32 has no trigger object). */
function triggerItems(i: ScriptInput) {
  return (i.triggers?.items ?? []).filter((t): t is Extract<typeof t, { ecas: unknown }> => "ecas" in t && t.type !== 16 && t.type !== 32);
}

/** The value a variable starts with: its initial value, else the type's default (CreateGroup() …). */
function initValue(i: ScriptInput, v: Variable): string | null {
  const data = i.data;
  if (v.initialized) {
    const preset = data.presets.get(v.initialValue);
    if (preset) return preset.script;
    return literal(data, v.type, v.initialValue);
  }
  // By the trigger type itself: unitcode is an integer in JASS but has no default. war3map.lua starts reals at 0.0.
  if (i.lua && v.type === "real") return "0.0";
  const def = TYPE_DEFAULTS[v.type];
  return def ?? null;
}
/** [TriggerTypeDefaults] of the game's TriggerData.txt. */
const TYPE_DEFAULTS: Record<string, string> = {
  boolean: "false", integer: "0", real: "0", string: '""', group: "CreateGroup()", force: "CreateForce()", timer: "CreateTimer()", dialog: "DialogCreate()",
};

export function initGlobals(i: ScriptInput): string {
  const vars = i.triggers?.variables ?? [];
  const lines = ["function InitGlobals takes nothing returns nothing"];
  if (vars.some((v) => v.isArray)) lines.push("    local integer i = 0");
  for (const v of vars) {
    const value = initValue(i, v);
    if (value === null) continue;
    if (!v.isArray) { lines.push(`    set udg_${v.name} = ${value}`); continue; }
    lines.push("    set i = 0", "    loop", `        exitwhen (i > ${v.arraySize})`, `        set udg_${v.name}[i] = ${value}`, "        set i = i + 1", "    endloop", "");
  }
  lines.push("endfunction", "", "");
  return lines.join(EOL);
}

/** In Lua maps the map's own code is Lua already: copied line by line (lua.ts RAW). */
const codeLines = (i: ScriptInput, t: string) => (i.lua ? t.split(/\r?\n/).map((l) => RAW + l + EOL).join("") : t.replace(/\r?\n/g, EOL) + EOL);

/** The first "Custom Script Code" section, after the globals: the script items (Reforged), each under
 *  its own banner. The map's custom script header isn't here: see mapHeader. */
export function customScript(i: ScriptInput): string {
  const scripts = i.triggers ? scriptItems({ triggers: i.triggers, custom: i.custom }) : [];
  if (!scripts.length) return banner("Custom Script Code");
  // With script items the banner's empty line moves to the end of the section.
  return banner("Custom Script Code").slice(0, -EOL.length)
    + scripts.map((s) => `${STARS}${EOL}//*  ${s.name}${EOL}${s.text ? codeLines(i, s.text) : ""}`).join("") + EOL;
}

/** The key of the second "Custom Script Code" section in generateSections and splitSections. */
export const HEADER_SECTION = "Custom Script Code (header)";

/** The map's custom script header (war3map.wct), under a second "Custom Script Code" banner after the
 *  map's objects (Regions, Cameras) and before the triggers, as the World Editor writes it; the first
 *  banner after the globals stays empty then (all six game maps with a header: War3XBonusCredits,
 *  Human06, WormWar, BomberCommand, AzerothGrandPrix, and the Lua map SilverpineSprint). The text as it
 *  is, its leading empty lines too (BomberCommand). Nothing for an empty header or one of only line breaks;
 *  one of spaces is written (war3map.lua, World Editor 2026-11-12: "   " stays a line; no game map has
 *  such a header, so JASS is taken to do the same). */
export function mapHeader(i: ScriptInput): string {
  const text = i.custom?.header ?? "";
  if (!/[^\r\n]/.test(text)) return "";
  return banner("Custom Script Code").slice(0, -EOL.length) + codeLines(i, text);
}

export function sounds(i: ScriptInput): string {
  // Sections for objects the map doesn't have are left out.
  if (!i.sounds?.length) return "";
  const lines = ["function InitSounds takes nothing returns nothing"];
  for (const s of i.sounds ?? []) {
    const n = s.name;
    // Music is only its file path.
    if (s.flags & 8) { lines.push(`    set ${n} = ${str(s.file)}`); continue; }
    const f = (bit: number) => ((s.flags & bit) !== 0 ? "true" : "false");
    lines.push(`    set ${n} = CreateSound( ${str(s.file)}, ${f(1)}, ${f(2)}, ${f(4)}, ${s.fadeInRate}, ${s.fadeOutRate}, ${str(s.eaxEffect)} )`);
    if (s.assetLabel && s.assetLabel !== "") lines.push(`    call SetSoundParamsFromLabel( ${n}, ${str(s.assetLabel)} )`);
    // A facial animation label without its group isn't written.
    if (s.facialAnimationLabel && s.facialAnimationGroupLabel) lines.push(`    call SetSoundFacialAnimationLabel( ${n}, ${str(s.facialAnimationLabel)} )`);
    if (s.facialAnimationGroupLabel) lines.push(`    call SetSoundFacialAnimationGroupLabel( ${n}, ${str(s.facialAnimationGroupLabel)} )`);
    if (s.facialAnimationSetFile) lines.push(`    call SetSoundFacialAnimationSetFilepath( ${n}, ${str(s.facialAnimationSetFile)} )`);
    // The dialogue keys, by the word after the facial animation file ("unknown2"), as counted over the game's maps:
    // 0 on a dialogue (a speaker unit type or a key set) writes both as they are, -1 too (OrcX02_02); otherwise the
    // keys set are written from editor 7000 on, none before (Undead04, HumanX04 in their 6127 and 7003 versions).
    // The game's maps have no 0 on a sound without a dialogue: the Sound Editor gives a new sound 1, as they have.
    const spoken = s.unknown2 === 0 && (!!s.speakerUnitType || (s.speakerNameKey ?? -1) >= 0 || (s.dialogueTextKey ?? -1) >= 0);
    const dialogue = (key: number | undefined) => key !== undefined && (spoken || (editorVersion(i) >= 7000 && key >= 0));
    if (dialogue(s.speakerNameKey)) lines.push(`    call SetDialogueSpeakerNameKey( ${n}, "TRIGSTR_${s.speakerNameKey}" )`);
    if (dialogue(s.dialogueTextKey)) lines.push(`    call SetDialogueTextKey( ${n}, "TRIGSTR_${s.dialogueTextKey}" )`);
    const duration = i.soundDuration?.(s.file, n);
    if (duration !== undefined) lines.push(`    call SetSoundDuration( ${n}, ${duration} )`);
    const label = s.assetLabel ? i.soundLabel?.(s.assetLabel) : undefined;
    if (label) {
      labelledSoundParams(lines, s, label);
      continue;
    }
    if (s.channel >= 0) lines.push(`    call SetSoundChannel( ${n}, ${s.channel} )`);
    lines.push(`    call SetSoundVolume( ${n}, ${s.volume} )`);
    if (!unset(s.pitch)) lines.push(`    call SetSoundPitch( ${n}, ${r1(s.pitch)} )`);
    if (s.flags & 2) {
      if (!unset(s.minDistance) || !unset(s.maxDistance)) lines.push(`    call SetSoundDistances( ${n}, ${r1(s.minDistance)}, ${r1(s.maxDistance)} )`);
      if (!unset(s.distanceCutoff)) lines.push(`    call SetSoundDistanceCutoff( ${n}, ${r1(s.distanceCutoff)} )`);
      if (!unset(s.coneInside)) lines.push(`    call SetSoundConeAngles( ${n}, ${r1(s.coneInside)}, ${r1(s.coneOutside)}, ${s.coneOutsideVolume} )`);
      if (!unset(s.coneOrientation[0])) lines.push(`    call SetSoundConeOrientation( ${n}, ${s.coneOrientation.map(r1).join(", ")} )`);
    }
  }
  lines.push("endfunction", "", "");
  return banner("Sound Assets") + lines.join(EOL);
}

/** A sound label's row in UI\SoundInfo (SetSoundParamsFromLabel applies it). */
export interface SoundLabel { channel: number; pitch: number; minDistance: number; maxDistance: number; distanceCutoff: number }

/** The sound lengths a map script sets (SetSoundDuration), JASS or Lua: for a sound by its name when it still plays
 *  the same file, else for its file. Sounds sharing a file keep their own: an unreadable file's length can only come
 *  from here, and Roundabout's three "---Invalid Sound Filepath---" sounds have three. */
export function scriptSoundDurations(script: string): (file: string, name: string) => number | undefined {
  const fileOf = new Map<string, string>();
  // JASS ("set x = CreateSound( "…"") or Lua ("x = CreateSound("…""); the path's escapes undone.
  for (const m of script.matchAll(/(\w+) = CreateSound\( ?"((?:[^"\\]|\\.)*)"/g)) fileOf.set(m[1], m[2].replace(/\\\\/g, "\\"));
  const byFile = new Map<string, number>(), byName = new Map<string, { file: string; ms: number }>();
  for (const m of script.matchAll(/SetSoundDuration\( ?(\w+), (\d+) ?\)/g)) {
    const file = fileOf.get(m[1]);
    if (file === undefined) continue;
    byFile.set(file, Number(m[2]));
    byName.set(m[1], { file, ms: Number(m[2]) });
  }
  return (file, name) => {
    const own = byName.get(name);
    return own?.file === file ? own.ms : byFile.get(file);
  };
}

/** Sound labels from the UI\SoundInfo tables (first row of a name wins; "_" is NaN, so never equal). */
/** The tables of UI\\SoundInfo (`${name}.slk`) that define sound labels. */
export const SOUND_INFO = ["AbilitySounds", "AmbienceSounds", "AmbientMusic", "AnimSounds", "CinematicSounds", "DialogSounds", "DialogueCreepsBase",
  "DialogueDemonBase", "DialogueHumanBase", "DialogueNagaBase", "DialogueNightElfBase", "DialogueOrcBase", "DialogueUndeadBase", "EAXDefs",
  "EnvironmentSounds", "Music", "PortraitAnims", "SoundAssetCombat", "UISounds", "UnitAckSounds", "UnitCombatSounds"];

export function parseSoundLabels(tables: string[]): Map<string, SoundLabel> {
  const out = new Map<string, SoundLabel>();
  for (const text of tables) {
    for (const r of parseSlk(text)) {
      if (!r.SoundName || out.has(r.SoundName)) continue;
      out.set(r.SoundName, { channel: Number(r.Channel), pitch: Number(r.Pitch), minDistance: Number(r.MinDistance), maxDistance: Number(r.MaxDistance), distanceCutoff: Number(r.DistanceCutoff) });
    }
  }
  return out;
}

/** Parameters of a labelled sound: unset values take their defaults, and only those the label
 *  doesn't already set are written (volume always, even -1; the cone of 3D sounds unless switched off). */
function labelledSoundParams(lines: string[], s: SoundJson, label: SoundLabel) {
  const n = s.name, or = (v: number, d: number) => (unset(v) ? d : v);
  const channel = s.channel >= 0 ? s.channel : 0;
  if (channel !== label.channel) lines.push(`    call SetSoundChannel( ${n}, ${channel} )`);
  lines.push(`    call SetSoundVolume( ${n}, ${s.volume} )`);
  const pitch = or(s.pitch, 1);
  if (Math.fround(pitch) !== label.pitch) lines.push(`    call SetSoundPitch( ${n}, ${r1(pitch)} )`);
  if (!(s.flags & 2)) return;
  const min = or(s.minDistance, 0), max = or(s.maxDistance, 10000), cutoff = or(s.distanceCutoff, 3000);
  if (Math.fround(min) !== label.minDistance || Math.fround(max) !== label.maxDistance) lines.push(`    call SetSoundDistances( ${n}, ${r1(min)}, ${r1(max)} )`);
  if (Math.fround(cutoff) !== label.distanceCutoff) lines.push(`    call SetSoundDistanceCutoff( ${n}, ${r1(cutoff)} )`);
  if (s.coneOutsideVolume !== -1) lines.push(`    call SetSoundConeAngles( ${n}, ${r1(or(s.coneInside, 0))}, ${r1(or(s.coneOutside, 0))}, ${s.coneOutsideVolume} )`);
  if (!unset(s.coneOrientation[0])) lines.push(`    call SetSoundConeOrientation( ${n}, ${s.coneOrientation.map(r1).join(", ")} )`);
}

export function regions(i: ScriptInput): string {
  if (!i.regions?.length) return "";
  const lines = ["function CreateRegions takes nothing returns nothing", "    local weathereffect we", ""];
  for (const r of sortedRegions(i)) {
    const n = `gg_rct_${ident(r.name)}`;
    lines.push(`    set ${n} = Rect( ${r1(r.left)}, ${r1(r.bottom)}, ${r1(r.right)}, ${r1(r.top)} )`);
    if (r.weather && r.weather !== "0x00000000") lines.push(`    set we = AddWeatherEffect( ${n}, '${r.weather}' )`, "    call EnableWeatherEffect( we, true )");
    if (r.sound) {
      // The ambient sound sits at the region's centre, on the ground, and covers the region.
      const x = (r.left + r.right) / 2, y = (r.bottom + r.top) / 2;
      // The World Editor's ground height differs from heightAt by up to 0.1 here.
      lines.push(`    call SetSoundPosition( ${r.sound}, ${r1(x)}, ${r1(y)}, ${r1(i.groundHeight?.(x, y) ?? 0)} )`,
        `    call RegisterStackedSound( ${r.sound}, true, ${r1(r.right - r.left)}, ${r1(r.top - r.bottom)} )`);
    }
  }
  lines.push("endfunction", "", "");
  return banner("Regions") + lines.join(EOL);
}

export function cameras(i: ScriptInput): string {
  if (!i.cameras?.length) return "";
  const lines = ["function CreateCameras takes nothing returns nothing", ""];
  for (const given of i.cameras ?? []) {
    const c = { ...given };
    const v3 = c.dofDistance !== undefined || c.unknown !== undefined;
    nameDepthOfField(c);
    const n = `gg_cam_${ident(c.name)}`;
    const field = (f: string, v: number) => `    call CameraSetupSetField( ${n}, CAMERA_FIELD_${f}, ${r1(v)}, 0.0 )`;
    lines.push(`    set ${n} = CreateCameraSetup(  )`,
      field("ZOFFSET", c.zOffset), field("ROTATION", c.rotation), field("ANGLE_OF_ATTACK", c.angleOfAttack),
      field("TARGET_DISTANCE", c.distance), field("ROLL", c.roll), field("FIELD_OF_VIEW", c.fieldOfView), field("FARZ", c.farZ),
      field("NEARZ", c.nearZ), field("LOCAL_PITCH", c.localPitch ?? 0), field("LOCAL_YAW", c.localYaw ?? 0), field("LOCAL_ROLL", c.localRoll ?? 0));
    // Only the newer camera file has these (war3map.w3c v3; v0 is the old form).
    if (v3) lines.push(field("DEPTH_OF_FIELD_DISTANCE", c.dofDistance ?? 0), field("DEPTH_OF_FIELD_SCALE", c.dofScale ?? 0), field("ZABSOLUTE", c.posAbsoluteZ ?? 0));
    lines.push(`    call CameraSetupSetDestPosition( ${n}, ${r1(c.targetX)}, ${r1(c.targetY)}, 0.0 )`);
    if (v3) lines.push(`    call BlzCameraSetupSetCameraType( ${n}, ${c.trailer ?? 0} )`);
    lines.push("");
  }
  lines.push("endfunction", "", "");
  return banner("Cameras") + lines.join(EOL);
}

/** The sections generated so far, keyed by banner title ("" = the header before the first). */
export function generateSections(i: ScriptInput): Map<string, string> {
  const destructables = destructableObjects(i), items = placedItems(i), groups = randomGroups(i), units = unitCreation(i);
  const techs = techSections(i);
  const sections = new Map([
    ["", header(i)],
    ["Global Variables", banner("Global Variables") + globals(i) + initGlobals(i)],
    ["Custom Script Code", customScript(i)],
    ["Random Groups", groups],
    ["Map Item Tables", mapItemTables(i)],
    ["Unit Item Tables", unitDrops(i)],
    ["Destructible Item Tables", destructableDrops(i)],
    ["Sound Assets", sounds(i)],
    ["Destructable Objects", destructables],
    ["Regions", regions(i)],
    ["Cameras", cameras(i)],
    ["Items", items],
    ["Unit Creation", units],
    [HEADER_SECTION, mapHeader(i)],
    ...techs,
    ["Triggers", i.triggers ? banner("Triggers") + triggersSection({ data: i.data, triggers: i.triggers, custom: i.custom, lua: i.lua }) : ""],
    ...setupSections(i, { destructables: !!destructables, items: !!items, randomGroups: !!groups, units: !!units, upgrades: !!techs[0][1], techs: !!techs[1][1] }),
  ]);
  // Sections of functions end with a blank line, the drop tables with two.
  // The map's header stays as the map has it.
  for (const [k, v] of sections) {
    if (!v || k === HEADER_SECTION || !/endfunction\s*$/.test(v)) continue;
    const blanks = k.endsWith("Item Tables") ? 2 : 1;
    sections.set(k, v.replace(/(\r\n)*$/, EOL.repeat(1 + blanks)));
  }
  return sections;
}

const editorVersion = (i: ScriptInput) => (i.info.editorVersion as number | undefined) ?? 0;
/** The build of war3map.w3i's gameVersion [major, minor, patch, build], if it has one. */
const gameBuild = (i: ScriptInput) => { const v = i.info.gameVersion; return Array.isArray(v) && typeof v[3] === "number" ? v[3] : undefined; };

function randomGroups(i: ScriptInput): string {
  const body = randomGroupsSection((i.info.unitTables as RandomGroupJson[] | undefined) ?? []);
  return body ? banner("Random Groups") + body : "";
}

function mapItemTables(i: ScriptInput): string {
  const body = itemTablesSection((i.info.itemTables as { number: number; sets: DropItem[][] }[] | undefined) ?? [], editorVersion(i));
  return body ? banner("Map Item Tables") + body : "";
}

/** The numbers of the map's item tables. */
const tableNumbers = (i: ScriptInput) => new Set(((i.info.itemTables as { number: number }[] | undefined) ?? []).map((t) => t.number));

function unitDrops(i: ScriptInput): string {
  const body = dropSection("Unit", (i.units ?? []) as Dropper[], editorVersion(i), tableNumbers(i));
  return body ? banner("Unit Item Tables") + body : "";
}

function destructableDrops(i: ScriptInput): string {
  const body = dropSection("Doodad", (i.doodads ?? []) as Dropper[], editorVersion(i), tableNumbers(i));
  return body ? banner("Destructible Item Tables") + body : "";
}

function destructableObjects(i: ScriptInput): string {
  const body = destructablesSection({ itemTables: tableNumbers(i), doodads: (i.doodads ?? []) as unknown as DestructableJson[], globalName: (d) => placedName(d as unknown as PlacedJson, "dest"),
    referenced: referencedGlobals(i, true), editorVersion: i.info.editorVersion as number | undefined, tint: i.destructableTint });
  return body ? banner("Destructable Objects") + body : "";
}

function placedItems(i: ScriptInput): string {
  if (!i.kindOf || !i.units?.length) return "";
  const body = itemsSection({ editorVersion: i.info.editorVersion as number | undefined, gameBuild: gameBuild(i), gameDataVersion: i.info.gameDataVersion as number | undefined, units: i.units as unknown as UnitJson[], kindOf: (id) => { const k = i.kindOf!(id); return k === "ability" ? undefined : k; }, referenced: referencedGlobals(i, true) });
  return body ? banner("Items") + body : "";
}

function unitCreation(i: ScriptInput): string {
  if (!i.kindOf || !i.units?.length) return "";
  const regions = i.regions ?? [];
  const body = unitsSection({
    itemTables: tableNumbers(i),
    units: i.units as unknown as UnitJson[], kindOf: (id) => { const k = i.kindOf!(id); return k === "ability" ? undefined : k; }, referenced: referencedGlobals(i, true), autocastOrders: i.autocastOrders, heroAbility: i.heroAbility, teamColor: i.teamColor, goldMine: i.goldMine, waygate: i.waygate, customColor: i.customColor,
    regionName: (n) => { const r = regions.find((x) => x.index === n); return r ? `gg_rct_${ident(r.name)}` : undefined; },
  });
  return body ? banner("Unit Creation") + body : "";
}

function techSections(i: ScriptInput): [string, string][] {
  const ids = ((i.info.players as { id: number }[] | undefined) ?? []).map((p) => p.id).sort((a, b) => a - b);
  const up = upgradesSection(ids, (i.info.upgrades as UpgradeJson[] | undefined) ?? []);
  const tech = techTreeSection(ids, (i.info.techs as TechJson[] | undefined) ?? [], (id) => i.kindOf?.(id) === "ability");
  return [["Upgrades", up ? banner("Upgrades") + up : ""], ["TechTree", tech ? banner("TechTree") + tech : ""]];
}

/** `made`: which sections were written (main calls only functions that exist; start locations
 *  alone make no Unit Creation section). */
function setupSections(i: ScriptInput, made: { destructables: boolean; items: boolean; randomGroups: boolean; units: boolean; upgrades: boolean; techs: boolean }): [string, string][] {
  const info = i.info as unknown as SetupInput["info"];
  const items = i.triggers?.items ?? [];
  const setup: SetupInput = {
    info, lights: i.lights ?? { terrain: "", unit: "" },
    has: {
      sounds: !!i.sounds?.length, regions: !!i.regions?.length, cameras: !!i.cameras?.length,
      ...made,
      triggers: !!i.triggers,
      initTriggers: items.some((t) => "ecas" in t && t.enabled && !t.isComment && runsAtInit(t)),
    },
  };
  return [
    ["Players", banner("Players") + playersSection(setup)],
    ["Main Initialization", banner("Main Initialization") + mainSection(setup)],
    ["Map Configuration", banner("Map Configuration") + configSection(setup)],
  ];
}

/** Splits a World Editor script at its section banners (same keys as generateSections). */
export function splitSections(script: string): Map<string, string> {
  const out = new Map<string, string>();
  const re = /\/\/\*{75}\r?\n\/\/\*\r?\n\/\/\*  (.+?)\r?\n\/\/\*\r?\n\/\/\*{75}\r?\n/g;
  let last = 0, title = "";
  for (const m of script.matchAll(re)) {
    out.set(title, script.slice(last, m.index));
    // The second "Custom Script Code" holds the map's header (mapHeader).
    title = m[1] === "Custom Script Code" && out.has(m[1]) ? HEADER_SECTION : m[1];
    last = m.index!;
  }
  out.set(title, script.slice(last));
  return out;
}

/** Section order of a World Editor war3map.j. */
const SECTION_ORDER = ["", "Global Variables", "Custom Script Code", "Random Groups", "Map Item Tables", "Unit Item Tables", "Destructible Item Tables",
  "Sound Assets", "Destructable Objects", "Items", "Unit Creation", "Regions", "Cameras", HEADER_SECTION, "Triggers", "Upgrades", "TechTree",
  "Players", "Main Initialization", "Map Configuration"];

/** The whole map script as the World Editor writes it: war3map.j, or war3map.lua for Lua maps
 *  (scriptType 1; the same functions, translated by lua.ts). */
export function generateScript(i: ScriptInput): string {
  const lua = i.info.scriptType === 1;
  const sections = generateSections({ ...i, lua });
  const jass = SECTION_ORDER.map((k) => sections.get(k) ?? "").join("");
  return lua ? jassToLua(jass) : jass;
}
